type ConfigKeys = (typeof GlobalMenuItems)[number][number]['key']

export type WithShow<T> = T & {
  /** Enables overriding the default to hide/show the menu-item on selective configurations */
  show?: boolean
}

type NavMenuOverrides = Partial<Record<ConfigKeys, Partial<WithShow<Pick<GlobalNavMenuItem, 'href'>>>>>

export type GlobalNavMenuProps = NavMenuOverrides & {
  /**
   * If the menu is currently open or not
   * Even when the menu is closed, this is required to support user hot-keys for menu items behind the menu.
   * @default true
   */
  open?: boolean

  richContent?: {
    /**
     * Enables the display of rich content in the navigation menu.
     * This is used to display dynamic content such as repositories.
     *
     * @default false
     */
    show?: boolean

    /**
     * The location to pull the initial config for rich content from.
     * These endpoints should return the initial data required to populate repositories.
     * If `richContentEnabled` is false or not provided, these URLs will be ignored.
     */
    contentUrl?: string

    repositoriesSearchUrl?: string
  }
}

/**
 * The main navigation menu component for the application.
 * It renders a side navigation menu with support for rich content.
 *
 * Handling for specific menu-items can be controlled via the individual props:
 * i.e.
 * ```tsx
 * <GlobalNavMenu
 *   home={{ show: true, href: '/custom-home' }}
 *   issues={{ show: false }}
 * />
 * ```
 *
 */
export function GlobalNavMenu(props: GlobalNavMenuProps & Pick<DialogProps, 'onClose' | 'returnFocusRef'>) {
  const {open = true, onClose, richContent} = props

  const [mainGroup, secondaryGroup] = GlobalMenuItems.map(group => {
    return group
      .filter(item => {
        if (props[item.key]?.show !== undefined) {
          return props[item.key]?.show
        }

        return item.show !== false
      })
      .map(({show: _show, ...item}) => {
        const {show, ...overrides} = props[item.key] ?? {}

        // Conditionally set copilot href and analytics key based on feature flags
        const copilotExperimentOverride = {}
        if (item.key === 'copilot') {
          let analyticsKey = item.analyticsKey
          if (isFeatureEnabled('copilot_default_to_task_input')) {
            analyticsKey += '_TASK'
            Object.assign(copilotExperimentOverride, {
              href: '/copilot/agents',
            })
          }
          if (isFeatureEnabled('copilot_default_to_task_input_control_group')) {
            analyticsKey += '_TASK_EXPERIMENT_CONTROL'
          }
          Object.assign(copilotExperimentOverride, {
            analyticsKey,
          })
        }

        return {
          ...item,
          ...overrides,
          ...copilotExperimentOverride,
        }
      })
  })

  return (
    <GlobalNavAnalyticsProvider category={analyticsCategory}>
      <GlobalNavCommands menuItems={[...(mainGroup ?? []), ...(secondaryGroup ?? [])]} />

      {open && (
        <SideNavMenu onClose={onClose}>
          <NavList.Group>
            {mainGroup?.map(({key, ...item}) => {
              return <SideNavMenuItem key={key} {...item} />
            })}
          </NavList.Group>

          {(secondaryGroup?.length ?? 0) > 0 && (
            <NavList.Group>
              {secondaryGroup?.map(({key, ...item}) => {
                return <SideNavMenuItem key={key} {...item} />
              })}
            </NavList.Group>
          )}
          {richContent?.show && richContent.contentUrl && (
            <DynamicSidePanelContent
              richContentUrl={richContent.contentUrl}
              repositoriesSearchUrl={richContent.repositoriesSearchUrl}
            />
          )}
        </SideNavMenu>
      )}
    </GlobalNavAnalyticsProvider>
  )
}

/**
 * Render the global UI commands provider for menu items (rendered even when the menu is closed).
 */
export function GlobalNavCommands({menuItems}: {menuItems: GlobalNavMenuItem[]}) {
  const {sendItemClick} = useGlobalNavAnalytics()

  const commandEntries = menuItems
    .filter((item): item is GlobalNavMenuItem & {commandId: GlobalNavigationCommandId} => item.commandId !== undefined)
    .map(
      ({commandId, href, analyticsKey}) =>
        [
          commandId,
          () => {
            window.location.assign(href)
            if (analyticsKey) {
              sendItemClick(analyticsKey)
            }
          },
        ] as const,
    )

  return <GlobalCommands commands={Object.fromEntries(commandEntries)} />
}

export function GlobalNavMenuPartial({reactPartialAnchor, ...props}: PropsWithPartialAnchor<GlobalNavMenuProps>) {
  const {ref: anchorRef, open, setOpen} = useExternalAnchor(reactPartialAnchor)

  const onClose = useCallback(() => {
    setOpen(false)
  }, [setOpen])

  return <GlobalNavMenu returnFocusRef={anchorRef} open={open} onClose={onClose} {...props} />
}

export type GlobalNavMenuItem = SideNavMenuItemProps & {
  /** The config key to use when overriding props */
  key: string
  /** Optional UI Command ID to trigger the menu item */
  commandId?: GlobalNavigationCommandId
}

